window.CHUJI_DATA_13 = [{"l": 421, "lt": "Lesson 121 The Greatest Killers 最大的杀手", "i": 1, "type": "reading", "en": "Alcohol and cigarettes are the two greatest killers in the world.", "zh": "酒精和香烟是世界上两大杀手。", "audio": "chuji_l121_01.mp3", "localAudio": "audio_chunks/chuji_l121_01.mp3", "b64": "", "src": "chuji"}, {"l": 421, "lt": "Lesson 121 The Greatest Killers 最大的杀手", "i": 2, "type": "reading", "en": "Hundreds of thousands of people have died because of these two social evils.", "zh": "几十万人已经死于这两种社会祸害。", "audio": "chuji_l121_02.mp3", "localAudio": "audio_chunks/chuji_l121_02.mp3", "b64": "", "src": "chuji"}, {"l": 421, "lt": "Lesson 121 The Greatest Killers 最大的杀手", "i": 3, "type": "reading", "en": "As a result, some governments are trying to control the use of these drugs.", "zh": "因此，有些政府正设法管制这些麻醉品的使用。", "audio": "chuji_l121_03.mp3", "localAudio": "audio_chunks/chuji_l121_03.mp3", "b64": "", "src": "chuji"}, {"l": 421, "lt": "Lesson 121 The Greatest Killers 最大的杀手", "i": 4, "type": "reading", "en": "For example, in many countries, the legal age for drinking has been raised from eighteen to twenty-one.", "zh": "例如在许多国家，合法的饮酒年龄已由18岁提高到21岁。", "audio": "chuji_l121_04.mp3", "localAudio": "audio_chunks/chuji_l121_04.mp3", "b64": "", "src": "chuji"}, {"l": 421, "lt": "Lesson 121 The Greatest Killers 最大的杀手", "i": 5, "type": "reading", "en": "Some countries have even banned smoking in public places.", "zh": "有些国家甚至在公共场所禁烟。", "audio": "chuji_l121_05.mp3", "localAudio": "audio_chunks/chuji_l121_05.mp3", "b64": "", "src": "chuji"}, {"l": 421, "lt": "Lesson 121 The Greatest Killers 最大的杀手", "i": 6, "type": "reading", "en": "People can help each other live longer by simply discouraging these bad habits.", "zh": "人们只要劝阻这些恶习便能帮助彼此活得更久。", "audio": "chuji_l121_06.mp3", "localAudio": "audio_chunks/chuji_l121_06.mp3", "b64": "", "src": "chuji"}, {"l": 422, "lt": "Lesson 122 I Quit Smoking 我戒烟了", "i": 1, "type": "dialog", "en": "Hi, Susan! Do you have a light?", "zh": "嗨，苏珊！借个火好吗？", "audio": "chuji_l122_01.mp3", "localAudio": "audio_chunks/chuji_l122_01.mp3", "b64": "", "src": "chuji", "speaker": "Gary", "note": "说话人: Gary"}, {"l": 422, "lt": "Lesson 122 I Quit Smoking 我戒烟了", "i": 2, "type": "dialog", "en": "No. I quit smoking long ago.", "zh": "不。很久以前我就戒烟了。", "audio": "chuji_l122_02.mp3", "localAudio": "audio_chunks/chuji_l122_02.mp3", "b64": "", "src": "chuji", "speaker": "Susan", "note": "说话人: Susan"}, {"l": 422, "lt": "Lesson 122 I Quit Smoking 我戒烟了", "i": 3, "type": "dialog", "en": "That's good. Congratulations!", "zh": "那很好·祝贺你！", "audio": "chuji_l122_03.mp3", "localAudio": "audio_chunks/chuji_l122_03.mp3", "b64": "", "src": "chuji", "speaker": "Gary", "note": "说话人: Gary"}, {"l": 422, "lt": "Lesson 122 I Quit Smoking 我戒烟了", "i": 4, "type": "dialog", "en": "Why don't you quit as well?", "zh": "你何不也戒掉呢？", "audio": "chuji_l122_04.mp3", "localAudio": "audio_chunks/chuji_l122_04.mp3", "b64": "", "src": "chuji", "speaker": "Susan", "note": "说话人: Susan"}, {"l": 422, "lt": "Lesson 122 I Quit Smoking 我戒烟了", "i": 5, "type": "dialog", "en": "It's really difficult.", "zh": "那真得很困难。", "audio": "chuji_l122_05.mp3", "localAudio": "audio_chunks/chuji_l122_05.mp3", "b64": "", "src": "chuji", "speaker": "Gary", "note": "说话人: Gary"}, {"l": 422, "lt": "Lesson 122 I Quit Smoking 我戒烟了", "i": 6, "type": "dialog", "en": "Come on; where there's a will, there's a way.", "zh": "别这样嘛；有志者事竟成。", "audio": "chuji_l122_06.mp3", "localAudio": "audio_chunks/chuji_l122_06.mp3", "b64": "", "src": "chuji", "speaker": "Susan", "note": "说话人: Susan"}, {"l": 423, "lt": "Lesson 123 An Accident 一桩事故", "i": 1, "type": "reading", "en": "Sally and her husband, Jack, have both been driving for three years.", "zh": "萨莉和她丈夫杰克两人开车已有三年了。", "audio": "chuji_l123_01.mp3", "localAudio": "audio_chunks/chuji_l123_01.mp3", "b64": "", "src": "chuji"}, {"l": 423, "lt": "Lesson 123 An Accident 一桩事故", "i": 2, "type": "reading", "en": "Jack has always driven very carefully.", "zh": "杰克开车总是很小她的错。", "audio": "chuji_l123_02.mp3", "localAudio": "audio_chunks/chuji_l123_02.mp3", "b64": "", "src": "chuji"}, {"l": 423, "lt": "Lesson 123 An Accident 一桩事故", "i": 3, "type": "reading", "en": "He has never been in an accident.", "zh": "昨天萨莉撞到一棵树，她把她的错归罪于那棵树，她说她按了喇叭，但那棵树就是不让路。", "audio": "chuji_l123_03.mp3", "localAudio": "audio_chunks/chuji_l123_03.mp3", "b64": "", "src": "chuji"}, {"l": 424, "lt": "Lesson 124 Beautiful Shanghai 美丽的上海市", "i": 1, "type": "dialog", "en": "Have you ever been to Taidong?", "zh": "你曾去过台东吗？", "audio": "chuji_l124_01.mp3", "localAudio": "audio_chunks/chuji_l124_01.mp3", "b64": "", "src": "chuji", "speaker": "Bob", "note": "说话人: Bob"}, {"l": 424, "lt": "Lesson 124 Beautiful Shanghai 美丽的上海市", "i": 2, "type": "dialog", "en": "No, but I've been to Hualien.", "zh": "没有，但我去过花莲。", "audio": "chuji_l124_02.mp3", "localAudio": "audio_chunks/chuji_l124_02.mp3", "b64": "", "src": "chuji", "speaker": "Mary", "note": "说话人: Mary"}, {"l": 424, "lt": "Lesson 124 Beautiful Shanghai 美丽的上海市", "i": 3, "type": "dialog", "en": "Did you have a good time?", "zh": "你玩得高兴吗？", "audio": "chuji_l124_03.mp3", "localAudio": "audio_chunks/chuji_l124_03.mp3", "b64": "", "src": "chuji", "speaker": "Bob", "note": "说话人: Bob"}, {"l": 424, "lt": "Lesson 124 Beautiful Shanghai 美丽的上海市", "i": 4, "type": "dialog", "en": "Yes, Hualien is a beautiful city.", "zh": "是的，花莲是个美丽的城市。", "audio": "chuji_l124_04.mp3", "localAudio": "audio_chunks/chuji_l124_04.mp3", "b64": "", "src": "chuji", "speaker": "Mary", "note": "说话人: Mary"}, {"l": 425, "lt": "Lesson 125 Studying Seriously 认真地学", "i": 1, "type": "reading", "en": "John has been trying to learn how to play the guitar.", "zh": "约翰一直在学吉他。", "audio": "chuji_l125_01.mp3", "localAudio": "audio_chunks/chuji_l125_01.mp3", "b64": "", "src": "chuji"}, {"l": 425, "lt": "Lesson 125 Studying Seriously 认真地学", "i": 2, "type": "reading", "en": "He has been taking lessons for half a year.", "zh": "他去上课已有半年了。", "audio": "chuji_l125_02.mp3", "localAudio": "audio_chunks/chuji_l125_02.mp3", "b64": "", "src": "chuji"}, {"l": 425, "lt": "Lesson 125 Studying Seriously 认真地学", "i": 3, "type": "reading", "en": "However, he hasn't been studying seriously.", "zh": "不过，他并不是很认真地在学。", "audio": "chuji_l125_03.mp3", "localAudio": "audio_chunks/chuji_l125_03.mp3", "b64": "", "src": "chuji"}, {"l": 425, "lt": "Lesson 125 Studying Seriously 认真地学", "i": 4, "type": "reading", "en": "He has only been going to his lessons every now and then.", "zh": "他只是偶尔才去上一次课。", "audio": "chuji_l125_04.mp3", "localAudio": "audio_chunks/chuji_l125_04.mp3", "b64": "", "src": "chuji"}, {"l": 425, "lt": "Lesson 125 Studying Seriously 认真地学", "i": 5, "type": "reading", "en": "Moreover, he seldom practices.", "zh": "而且他很少练习。", "audio": "chuji_l125_05.mp3", "localAudio": "audio_chunks/chuji_l125_05.mp3", "b64": "", "src": "chuji"}, {"l": 425, "lt": "Lesson 125 Studying Seriously 认真地学", "i": 6, "type": "reading", "en": "On the other hand, his cousin, Tim, has been playing the guitar for about three months.", "zh": "另一方面，他的表哥蒂姆学吉他只有三个月左右。", "audio": "chuji_l125_06.mp3", "localAudio": "audio_chunks/chuji_l125_06.mp3", "b64": "", "src": "chuji"}, {"l": 425, "lt": "Lesson 125 Studying Seriously 认真地学", "i": 7, "type": "reading", "en": "He plays much better than John.", "zh": "他弹奏得要比约翰好多了。", "audio": "chuji_l125_07.mp3", "localAudio": "audio_chunks/chuji_l125_07.mp3", "b64": "", "src": "chuji"}, {"l": 425, "lt": "Lesson 125 Studying Seriously 认真地学", "i": 8, "type": "reading", "en": "Tim isn't more talented than John, though.", "zh": "然而蒂姆并不比约翰有天份。", "audio": "chuji_l125_08.mp3", "localAudio": "audio_chunks/chuji_l125_08.mp3", "b64": "", "src": "chuji"}, {"l": 425, "lt": "Lesson 125 Studying Seriously 认真地学", "i": 9, "type": "reading", "en": "He is just more determined.", "zh": "他只是更有决心而已。", "audio": "chuji_l125_09.mp3", "localAudio": "audio_chunks/chuji_l125_09.mp3", "b64": "", "src": "chuji"}, {"l": 426, "lt": "Lesson 126 Playing the Piano 弹钢琴", "i": 1, "type": "dialog", "en": "How long have you been playing the piano. Nancy?", "zh": "南希，你弹钢琴弹多久了？", "audio": "chuji_l126_01.mp3", "localAudio": "audio_chunks/chuji_l126_01.mp3", "b64": "", "src": "chuji", "speaker": "Able", "note": "说话人: Able"}, {"l": 426, "lt": "Lesson 126 Playing the Piano 弹钢琴", "i": 2, "type": "dialog", "en": "For about ten years.", "zh": "大约十年了。", "audio": "chuji_l126_02.mp3", "localAudio": "audio_chunks/chuji_l126_02.mp3", "b64": "", "src": "chuji", "speaker": "Nancy", "note": "说话人: Nancy"}, {"l": 426, "lt": "Lesson 126 Playing the Piano 弹钢琴", "i": 3, "type": "dialog", "en": "Wow! That's a long time. Can you teach me how to play?", "zh": "哇！那真是很久了。你可以教我弹钢琴吗？", "audio": "chuji_l126_03.mp3", "localAudio": "audio_chunks/chuji_l126_03.mp3", "b64": "", "src": "chuji", "speaker": "Able", "note": "说话人: Able"}, {"l": 426, "lt": "Lesson 126 Playing the Piano 弹钢琴", "i": 4, "type": "dialog", "en": "No problem.", "zh": "没问题。", "audio": "chuji_l126_04.mp3", "localAudio": "audio_chunks/chuji_l126_04.mp3", "b64": "", "src": "chuji", "speaker": "Nancy", "note": "说话人: Nancy"}, {"l": 427, "lt": "Lesson 127 An Honest Man 诚实的人", "i": 1, "type": "reading", "en": "If you are honest, people will trust you.", "zh": "你若诚实，人们就会信任你。", "audio": "chuji_l127_01.mp3", "localAudio": "audio_chunks/chuji_l127_01.mp3", "b64": "", "src": "chuji"}, {"l": 427, "lt": "Lesson 127 An Honest Man 诚实的人", "i": 2, "type": "reading", "en": "It is important for a person to have a reputation for being honest.", "zh": "对一个人来说，拥有诚实的信誉是很重要的。", "audio": "chuji_l127_02.mp3", "localAudio": "audio_chunks/chuji_l127_02.mp3", "b64": "", "src": "chuji"}, {"l": 427, "lt": "Lesson 127 An Honest Man 诚实的人", "i": 3, "type": "reading", "en": "If a person is dishonest, no one will want to be his friend.", "zh": "一个人若不诚实，就没有人会想和他做朋友。", "audio": "chuji_l127_03.mp3", "localAudio": "audio_chunks/chuji_l127_03.mp3", "b64": "", "src": "chuji"}, {"l": 427, "lt": "Lesson 127 An Honest Man 诚实的人", "i": 4, "type": "reading", "en": "He will soon become an outcast.", "zh": "不久他就会被人拒于千里之外。", "audio": "chuji_l127_04.mp3", "localAudio": "audio_chunks/chuji_l127_04.mp3", "b64": "", "src": "chuji"}, {"l": 427, "lt": "Lesson 127 An Honest Man 诚实的人", "i": 5, "type": "reading", "en": "On the other hand, an honest man wins the respect of others.", "zh": "另一方面说来，诚实的人会赢得别人的尊敬。", "audio": "chuji_l127_05.mp3", "localAudio": "audio_chunks/chuji_l127_05.mp3", "b64": "", "src": "chuji"}, {"l": 427, "lt": "Lesson 127 An Honest Man 诚实的人", "i": 6, "type": "reading", "en": "Honesty is, indeed, the best policy.", "zh": "诚实确实是上策。", "audio": "chuji_l127_06.mp3", "localAudio": "audio_chunks/chuji_l127_06.mp3", "b64": "", "src": "chuji"}, {"l": 428, "lt": "Lesson 128 The Job Interview 工作面试", "i": 1, "type": "dialog", "en": "How did the job interview go?", "zh": "面试进行得如何？", "audio": "chuji_l128_01.mp3", "localAudio": "audio_chunks/chuji_l128_01.mp3", "b64": "", "src": "chuji", "speaker": "Carrie", "note": "说话人: Carrie"}, {"l": 428, "lt": "Lesson 128 The Job Interview 工作面试", "i": 2, "type": "dialog", "en": "It went very well. Thanks.", "zh": "很顺利，谢谢。", "audio": "chuji_l128_02.mp3", "localAudio": "audio_chunks/chuji_l128_02.mp3", "b64": "", "src": "chuji", "speaker": "Jock", "note": "说话人: Jock"}, {"l": 428, "lt": "Lesson 128 The Job Interview 工作面试", "i": 3, "type": "dialog", "en": "What's the name of the company?", "zh": "公司的名称是什么？", "audio": "chuji_l128_03.mp3", "localAudio": "audio_chunks/chuji_l128_03.mp3", "b64": "", "src": "chuji", "speaker": "Carrie", "note": "说话人: Carrie"}, {"l": 428, "lt": "Lesson 128 The Job Interview 工作面试", "i": 4, "type": "dialog", "en": "Chunghwa Computers.", "zh": "中华电子计算机。", "audio": "chuji_l128_04.mp3", "localAudio": "audio_chunks/chuji_l128_04.mp3", "b64": "", "src": "chuji", "speaker": "Jock", "note": "说话人: Jock"}, {"l": 428, "lt": "Lesson 128 The Job Interview 工作面试", "i": 5, "type": "dialog", "en": "I've heard it has a good reputation.", "zh": "我听说它的名声很好。", "audio": "chuji_l128_05.mp3", "localAudio": "audio_chunks/chuji_l128_05.mp3", "b64": "", "src": "chuji", "speaker": "Carrie", "note": "说话人: Carrie"}, {"l": 428, "lt": "Lesson 128 The Job Interview 工作面试", "i": 6, "type": "dialog", "en": "That's why I applied for a job there.", "zh": "那就是我去那里求职的原因。", "audio": "chuji_l128_06.mp3", "localAudio": "audio_chunks/chuji_l128_06.mp3", "b64": "", "src": "chuji", "speaker": "Jock", "note": "说话人: Jock"}, {"l": 429, "lt": "Lesson 129 Seven Years' Bad Luck 七年的背运", "i": 1, "type": "reading", "en": "I have a very superstitious friend called Mack.", "zh": "我有个非常迷信的朋友名叫麦克。", "audio": "chuji_l129_01.mp3", "localAudio": "audio_chunks/chuji_l129_01.mp3", "b64": "", "src": "chuji"}, {"l": 429, "lt": "Lesson 129 Seven Years' Bad Luck 七年的背运", "i": 2, "type": "reading", "en": "He thinks that if he breaks a mirror, he will have seven years' bad luck.", "zh": "他认为他若打破镜子，他将会有七年的背运。", "audio": "chuji_l129_02.mp3", "localAudio": "audio_chunks/chuji_l129_02.mp3", "b64": "", "src": "chuji"}, {"l": 429, "lt": "Lesson 129 Seven Years' Bad Luck 七年的背运", "i": 3, "type": "reading", "en": "As a result, Mack doesn't have any mirrors in his house.", "zh": "因此，麦克的屋子里什么镜子也没有。", "audio": "chuji_l129_03.mp3", "localAudio": "audio_chunks/chuji_l129_03.mp3", "b64": "", "src": "chuji"}, {"l": 429, "lt": "Lesson 129 Seven Years' Bad Luck 七年的背运", "i": 4, "type": "reading", "en": "But not all superstitions are about bad luck.", "zh": "不过，并非所有的迷信都与背运有关。", "audio": "chuji_l129_04.mp3", "localAudio": "audio_chunks/chuji_l129_04.mp3", "b64": "", "src": "chuji"}, {"l": 429, "lt": "Lesson 129 Seven Years' Bad Luck 七年的背运", "i": 5, "type": "reading", "en": "For instance, Mack also believes that if he drops his chopsticks, someone will invite him to dinner.", "zh": "举例来说，麦克也相信他若把筷子掉下去，就会有人请他吃晚餐。", "audio": "chuji_l129_05.mp3", "localAudio": "audio_chunks/chuji_l129_05.mp3", "b64": "", "src": "chuji"}, {"l": 429, "lt": "Lesson 129 Seven Years' Bad Luck 七年的背运", "i": 6, "type": "reading", "en": "So, Mack is always dropping his chopsticks and waiting for an invitation.", "zh": "因此，麦克总是把筷子掉下去，然后等着别人来邀请。", "audio": "chuji_l129_06.mp3", "localAudio": "audio_chunks/chuji_l129_06.mp3", "b64": "", "src": "chuji"}, {"l": 430, "lt": "Lesson 130 He Will Bite You 它会咬你", "i": 1, "type": "dialog", "en": "Don't pull the dog's tail!", "zh": "不要扯狗的尾巴！", "audio": "chuji_l130_01.mp3", "localAudio": "audio_chunks/chuji_l130_01.mp3", "b64": "", "src": "chuji", "speaker": "Mother", "note": "说话人: Mother"}, {"l": 430, "lt": "Lesson 130 He Will Bite You 它会咬你", "i": 2, "type": "dialog", "en": "Why? What will happen if I do?", "zh": "为什么？如果我扯的话会怎么样？", "audio": "chuji_l130_02.mp3", "localAudio": "audio_chunks/chuji_l130_02.mp3", "b64": "", "src": "chuji", "speaker": "Son", "note": "说话人: Son"}, {"l": 430, "lt": "Lesson 130 He Will Bite You 它会咬你", "i": 3, "type": "dialog", "en": "If you pull his tail, he will bite you.", "zh": "如果你扯它的尾巴，它就会咬你。", "audio": "chuji_l130_03.mp3", "localAudio": "audio_chunks/chuji_l130_03.mp3", "b64": "", "src": "chuji", "speaker": "Mother", "note": "说话人: Mother"}, {"l": 430, "lt": "Lesson 130 He Will Bite You 它会咬你", "i": 4, "type": "dialog", "en": "No, he won't. I pulled out all his teeth this morning.", "zh": "不，它不会。今天早上我把它全部的牙齿都拔光了。", "audio": "chuji_l130_04.mp3", "localAudio": "audio_chunks/chuji_l130_04.mp3", "b64": "", "src": "chuji", "speaker": "Son", "note": "说话人: Son"}];